import 'dart:async';
import 'package:flutter/material.dart';
import '../theme/app_theme.dart';
import 'welcome_screen.dart';
class SplashScreen extends StatefulWidget{const SplashScreen({super.key});@override State<SplashScreen> createState()=>_SplashScreenState();}
class _SplashScreenState extends State<SplashScreen> with SingleTickerProviderStateMixin{late final AnimationController _controller;late final Animation<double> _fade;late final Animation<double> _scale;Timer? _timer;@override void initState(){super.initState();_controller=AnimationController(vsync:this,duration:const Duration(milliseconds:1100));_fade=CurvedAnimation(parent:_controller,curve:Curves.easeOut);_scale=Tween<double>(begin:.88,end:1).animate(CurvedAnimation(parent:_controller,curve:Curves.easeOutBack));_controller.forward();_timer=Timer(const Duration(milliseconds:2300),_openWelcome);}_openWelcome(){if(!mounted)return;Navigator.of(context).pushReplacement(PageRouteBuilder(pageBuilder:(_,__,___)=>const WelcomeScreen(),transitionDuration:const Duration(milliseconds:450),transitionsBuilder:(_,a,__,child)=>FadeTransition(opacity:a,child:child)));}@override void dispose(){_timer?.cancel();_controller.dispose();super.dispose();}@override Widget build(BuildContext context)=>Scaffold(body:Stack(fit:StackFit.expand,children:[const ColoredBox(color:Colors.white),Positioned.fill(child:Image.asset('assets/logo.png',fit:BoxFit.contain,alignment:Alignment.center,filterQuality:FilterQuality.high)),Positioned.fill(child:DecoratedBox(decoration:BoxDecoration(gradient:LinearGradient(begin:Alignment.topCenter,end:Alignment.bottomCenter,colors:[Colors.white.withOpacity(.02),Colors.white.withOpacity(.05),Colors.white.withOpacity(.94)],stops:const[0,.55,1])))),Positioned(left:24,right:24,bottom:46,child:FadeTransition(opacity:_fade,child:ScaleTransition(scale:_scale,child:Column(children:[Text('YOUR CITY. YOUR SERVICES.',textAlign:TextAlign.center,style:Theme.of(context).textTheme.labelLarge?.copyWith(color:AppColors.primaryDark,letterSpacing:2.2,fontWeight:FontWeight.w800)),const SizedBox(height:16),Container(width:30,height:3,decoration:BoxDecoration(color:AppColors.accent,borderRadius:BorderRadius.circular(10))),const SizedBox(height:16),Text('One app. All services. Quality you can trust.',textAlign:TextAlign.center,style:Theme.of(context).textTheme.bodyMedium?.copyWith(color:AppColors.muted,fontWeight:FontWeight.w600)),const SizedBox(height:24),const SizedBox(width:22,height:22,child:CircularProgressIndicator(strokeWidth:2.4))]))))]));}
